module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

    reg [1:0] mul_en_in_reg;

    reg [7:0] mul_a_reg;

    reg [7:0] mul_b_reg;

    reg [1:0] mul_en_out_reg;

    reg [15:0] mul_out_reg;

    wire [7:0] temp[7:0];

    wire [15:0] sum[7:0];

    genvar i;
    generate
        for(i = 0; i < 8; i=i+1) begin : pp_gen
            assign temp[i] = {8{mul_b_reg[i]}} & ((i == 0) ? mul_a_reg : {{(i){1'b0}}, mul_a_reg} >> i);
        end
    endgenerate

    assign sum[0] = temp[0];
    generate
        for(i = 1; i <= 7; i=i+1) begin : ps_calc
            assign sum[i] = sum[i-1] + temp[i];
        end
    endgenerate

    assign mul_out = (mul_en_out_reg[1]) ? mul_out_reg : 16'd0;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            mul_en_out_reg <= 2'b0;
            mul_out_reg <= 16'd0;

            mul_en_in_reg <= 2'b0;
            mul_a_reg <= 8'd0;
            mul_b_reg <= 8'd0;
        end else begin

            mul_en_in_reg[0] <= mul_en_in;
            mul_en_in_reg[1] <= mul_en_in_reg[0];

            mul_en_out_reg[0] <= mul_en_in_reg[1];
            mul_en_out_reg[1] <= mul_en_out_reg[0];

            mul_out_reg <= sum[7];

            if(mul_en_in_reg[1]) begin
                mul_a_reg <= mul_a;
                mul_b_reg <= mul_b;
            end
        end
    end
endmodule
